<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserWebauthnCredential\Domain\ValueObject\Holder\UserWebauthnCredentialPublicKeyAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWebauthnCredentialPublicKeyAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserWebauthnCredentialPublicKeyAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getPublicKey returns null on a freshly created holder.
     */
    public function testPublicKeyNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialPublicKeyAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isPublicKeyAssigned());
        $this->assertNull($holder->getPublicKey());
    }
}
class ImplWithUserWebauthnCredentialPublicKeyAttributeHolderUnitTest
{
    use UserWebauthnCredentialPublicKeyAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedPublicKeyRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultPublicKey();
    }
}
